'use strict';

const fs = require('fs');
const data = fs.readFileSync(0);

let pos = 0;

function nextInt() {
  while (pos < data.length && data[pos] <= 32) pos++;
  let value = 0;
  while (pos < data.length && data[pos] > 32) {
    value = value * 10 + data[pos] - 48;
    pos++;
  }
  return value;
}

function nextChar() {
  while (pos < data.length && data[pos] <= 32) pos++;
  return String.fromCharCode(data[pos++]);
}

const N = nextInt();
const M = nextInt();
const P = nextInt();

const rows = new Uint32Array(N);
const cols = new Uint32Array(M);

for (let i = 0; i < N; i++) rows[i] = i;
for (let j = 0; j < M; j++) cols[j] = j;

for (let i = 0; i < P; i++) {
  const op = nextChar();
  const a = nextInt() - 1;
  const b = nextInt() - 1;

  const permutation = op === 'L' ? rows : cols;
  const temp = permutation[a];
  permutation[a] = permutation[b];
  permutation[b] = temp;
}

const parts = [];
let count = 0;

for (let i = 0; i < N; i++) {
  const rowBase = rows[i] * M;
  for (let j = 0; j < M; j++) {
    parts.push(String(rowBase + cols[j] + 1));
    parts.push(j + 1 === M ? '\n' : ' ');

    if (++count === 8192) {
      process.stdout.write(parts.join(''));
      parts.length = 0;
      count = 0;
    }
  }
}

if (parts.length > 0) process.stdout.write(parts.join(''));
